from pathlib import Path
import copy,importlib.util,json,tempfile,unittest,shutil,subprocess,sys
ROOT=Path(__file__).resolve().parents[1]/'skills/live-training-session-design'
spec=importlib.util.spec_from_file_location('demo_validator',ROOT/'scripts/validate_demo.py');v=importlib.util.module_from_spec(spec);spec.loader.exec_module(v)
BASE=json.loads((ROOT/'examples/demo/demo.json').read_text())
class DemoTests(unittest.TestCase):
 def setUp(self):self.d=copy.deepcopy(BASE)
 def errors(self):return v.validate(self.d,ROOT)
 def reject(self,phrase):self.assertTrue(any(phrase in e for e in self.errors()),self.errors())
 def test_valid_draft(self):self.assertEqual(self.errors(),[])
 def test_skill_structure(self):self.assertEqual(v.validate_skill(ROOT),[])
 def test_schema(self):self.d['schema_version']='old';self.reject('Unsupported schema')
 def test_document_version(self):self.d['artifact_version']='0';self.reject('Document version differs')
 def test_document_state(self):self.d['release_state']='Planning framework only';self.reject('Document state differs')
 def test_source_version(self):self.d['sources'][0]['version']='';self.reject('source metadata')
 def test_source_path(self):self.d['sources'][0]['path']='missing';self.reject('Missing/unsafe file')
 def test_duplicate_scene(self):self.d['scenes'].append(self.d['scenes'][0]);self.reject('Scene IDs must be unique')
 def test_scene_fields(self):self.d['scenes'][2]['narration']='';self.reject('missing scene narration')
 def test_objective_reference(self):self.d['scenes'][0]['objective_ids']=['bad'];self.reject('unknown reference')
 def test_unknown_action_source(self):self.d['actions'][0]['source_id']='bad';self.reject('unknown action source')
 def test_unclaimed_execution(self):self.d['actions'][0]['executed']=True;self.reject('actual execution requires separate evidence')
 def test_action_state(self):self.d['actions'][0]['to_state']='bad';self.reject('unknown action state')
 def test_read_action_mutation(self):self.d['actions'][0]['to_state']='T1';self.reject('read-only cannot change state')
 def test_unknown_retry(self):self.d['actions'][1]['retry_policy']='One retry after timeout';self.reject('unsafe unknown-outcome retry')
 def test_verify_before_retry(self):self.d['actions'][3]['verify_before_retry']=False;self.reject('verify before retry')
 def test_unknown_outcome_route(self):self.d['actions'][1]['on_unknown']='Retry immediately';self.reject('state check and switch')
 def test_missing_success_signal(self):self.d['actions'][3]['success_signal']='';self.reject('missing success_signal')
 def test_missing_authorization(self):self.d['actions'][3]['authorization']='';self.reject('missing authorization')
 def test_state_chain(self):self.d['scenes'][2]['entry_state']='T0';self.reject('broken action state chain')
 def test_scene_exit(self):self.d['scenes'][2]['exit_state']='T3';self.reject('scene exit differs')
 def test_recovery_reference(self):self.d['scenes'][0]['recovery_id']='bad';self.reject('matching recovery')
 def test_recovery_state_check(self):self.d['recoveries'][1]['state_check_required']=False;self.reject('recovery must check state')
 def test_recovery_asset(self):self.d['recoveries'][0]['asset_id']='bad';self.reject('backup reference')
 def test_recovery_budget(self):self.d['recoveries'][0]['max_seconds']=0;self.reject('recovery budget missing')
 def test_recovery_stop(self):self.d['recoveries'][0]['stop_rule']='';self.reject('missing stop_rule')
 def test_checkpoint_response(self):self.d['scenes'][0]['checkpoint']['response_mode']='';self.reject('incomplete checkpoint')
 def test_checkpoint_feedback(self):self.d['scenes'][0]['checkpoint']['facilitator_response']='';self.reject('incomplete checkpoint')
 def test_unknown_asset_source(self):self.d['assets'][0]['source_id']='bad';self.reject('unknown asset source')
 def test_missing_backup_file(self):self.d['assets'][0]['path']='absent.png';self.reject('Missing/unsafe file')
 def test_missing_backup_section(self):self.d['assets'][0]['quote']='nonexistent-state';self.reject('asset section unresolved')
 def test_stale_backup(self):self.d['assets'][0]['artifact_version']='0';self.reject('stale asset version')
 def test_false_verified_backup(self):self.d['assets'][0]['status']='Verified';self.reject('actual evidence missing')
 def test_planned_backup_prerequisite(self):self.d['assets'][0].update(status='Planned',path=None);self.reject('planned asset prerequisite')
 def test_path_total(self):self.d['paths'][0]['total_minutes']=11;self.reject('path total differs')
 def test_path_coverage(self):self.d['paths'][0]['steps'].pop();self.reject('coverage/order differs')
 def test_path_scene_time(self):self.d['paths'][0]['steps'][0]['minutes']=3;self.reject('scene duration differs')
 def test_component_arithmetic(self):self.d['paths'][0]['steps'][0]['components_seconds']['transition']=100;self.reject('component total differs')
 def test_checkpoint_allocation(self):self.d['paths'][0]['steps'][0]['components_seconds']['checkpoint']=0;self.reject('checkpoint exceeds allocation')
 def test_recovery_allocation(self):self.d['paths'][0]['steps'][0]['components_seconds']['recovery_reserve']=0;self.reject('recovery exceeds reserve')
 def test_prepared_dependency(self):self.d['paths'][1]['steps'][0]['entry_dependency']='bad';self.reject('prepared entry dependency')
 def test_prepared_omissions(self):self.d['paths'][1]['steps'][0]['omissions']=[];self.reject('must disclose omissions')
 def test_live_dependency(self):self.d['paths'][0]['steps'][0]['entry_dependency']='T3';self.reject('live entry dependency differs')
 def test_duration_order(self):self.d['scenes'][0]['durations']['compressed']=3;self.reject('variants out of order')
 def test_fallback_omissions(self):self.d['fallbacks'][0]['classification']='Equivalent';self.reject('cannot omit target evidence')
 def test_fallback_verification(self):self.d['fallbacks'][0]['verification_status']='Verified';self.reject('actual evidence missing')
 def test_fallback_proficiency(self):self.d['fallbacks'][0]['proficiency_use_allowed']=True;self.reject('cannot imply proficiency')
 def test_fallback_rationale(self):self.d['fallbacks'][0]['rationale']='';self.reject('missing rationale')
 def test_incomplete_practice(self):self.d['practice'][0]['fact_quotes'].append('an unsupplied deadline');self.reject('supplied fact missing')
 def test_missing_practice_model(self):self.d['practice'][0]['key_quote']='absent-key';self.reject('model key missing')
 def test_unknown_retry_asset(self):self.d['practice'][0]['retry_id']='missing';self.reject('unknown retry')
 def test_separate_key(self):self.d['key_path']=self.d['learner_path'];self.reject('separation required')
 def test_key_leak(self):
  with tempfile.TemporaryDirectory() as t:
   p=Path(t);shutil.copytree(ROOT/'examples',p/'examples');f=p/'examples/demo/learner-practice.md';f.write_text(f.read_text()+'\nFacilitator-only\n');self.assertTrue(any('contains key' in x for x in v.validate(self.d,p)))
 def test_outside_practice_time(self):self.d['practice_minutes_outside_demo']=None;self.reject('outside demo missing')
 def test_quality_coverage(self):self.d['quality_checks'].pop();self.reject('Thirteen individual')
 def test_quality_evidence(self):self.d['quality_checks'][0]['evidence_quote']='NONEXISTENT-REVIEW-EVIDENCE-991';self.reject('evidence quote unresolved')
 def test_stale_quality(self):self.d['quality_checks'][0]['artifact_version']='old';self.reject('stale quality version')
 def test_exclusion_not_pass(self):self.d['quality_checks'][-1]['status']='Pass';self.reject('exclusion cannot count as pass')
 def test_exclusion_rationale(self):self.d['quality_checks'][-1]['rationale']='';self.reject('rationale/scope')
 def test_known_defect(self):self.d['quality_checks'][0]['status']='Needs revision';self.reject('Known defect requires')
 def test_missing_rehearsal(self):self.d['rehearsals'].pop();self.reject('rehearsal records missing')
 def test_false_rehearsal(self):self.d['rehearsals'][0]['status']='Pass';self.reject('actual evidence missing')
 def test_false_authorization(self):self.d['release_authorization']['status']='Authorized';self.reject('actual evidence missing')
 def test_false_readiness(self):self.d['release_state']='Ready for delivery';self.reject('Readiness has unperformed');self.reject('verified assets');self.reject('actual rehearsals');self.reject('blocking open items');self.reject('actual authorization');self.reject('Fictional-only')
 def test_handoff_destinations(self):self.d['handoffs'][0]['destination']='other';self.reject('destinations differ')
 def test_handoff_execution(self):self.d['handoffs'][0]['status']='Executed';self.reject('cannot imply handoff execution')
 def test_handoff_findings(self):self.d['handoffs'][0]['finding_ids']=['F-999'];self.reject('handoff lost reference')
 def test_handoff_open_reference(self):self.d['handoffs'][0]['open_item_ids']=['missing'];self.reject('unknown reference')
 def test_handoff_acceptance(self):self.d['handoffs'][0]['acceptance']='';self.reject('scope/acceptance missing')
 def test_unsafe_path(self):self.d['sources'][0]['path']='../../../../../etc/passwd';self.reject('unsafe file')
 def test_verified_fallback_dependencies(self):
  self.d['fallbacks'][0]['verification_status']='Verified';self.reject('verified fallback requires verified assets')
 def test_bad_record(self):self.assertEqual(v.validate([],ROOT),['Record must be object'])
 def test_cli_malformed(self):
  with tempfile.TemporaryDirectory() as t:
   p=Path(t)/'bad.json';p.write_text('{bad');run=subprocess.run([sys.executable,str(ROOT/'scripts/validate_demo.py'),'--record',str(p)],capture_output=True,text=True);self.assertNotEqual(run.returncode,0);self.assertEqual(json.loads(run.stdout)['structural_validation'],'FAIL')
if __name__=='__main__':unittest.main(verbosity=2)
